import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fc_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fc_fwd_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int M,
    int K,
    int N
) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < M && col < N) {
        float val = 0.0f;
        for (int i = 0; i < K; i++) {
            val += input[row * K + i] * weight[col * K + i];
        }
        val += bias[col];
        output[row * N + col] = val;
    }
}

torch::Tensor fc_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    TORCH_CHECK(weight.dim() == 2, "Weight must be 2D");
    TORCH_CHECK(bias.dim() == 1, "Bias must be 1D");

    input = input.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();

    int M = input.size(0);
    int K = input.size(1);
    int N = weight.size(0);

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({M, N}, options);

    dim3 block(16, 16);
    dim3 grid((M + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    fc_fwd_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        M,
        K,
        N
    );

    return output;
}
"""

fc_cpp_source = "torch::Tensor fc_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

my_fc_layer = load_inline(
    name="my_fc_layer",
    cpp_sources=fc_cpp_source,
    cuda_sources=fc_source,
    extra_cflags=["-O3"],
    extra_ldflags=[],
    functions=["fc_forward"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.num_layers = num_layers
        self.output_size = output_size
        self.dropout = dropout

        # Default batch_size (as in the original code)
        self.batch_size = 10

        self.h0 = torch.randn((num_layers, self.batch_size, hidden_size))
        self.c0 = torch.randn((num_layers, self.batch_size, hidden_size))
        self.lstm = nn.LSTM(
            input_size,
            hidden_size,
            num_layers,
            batch_first=True,
            dropout=dropout,
            bidirectional=False
        )
        self.fc = nn.Linear(hidden_size, output_size)

    def forward(self, x):
        self.h0 = self.h0.to(x.device)
        self.c0 = self.c0.to(x.device)

        out, state = self.lstm(x, (self.h0, self.c0))
        out_last = out[:, -1, :]  
        out_fc = my_fc_layer.fc_forward(out_last, self.fc.weight, self.fc.bias)

        # Following the original code structure, return state[0]
        return state[0]
